// Filter tasks that need GitHub issues
const tasks = $input.first().json.tasks || [];
const githubTasks = tasks.filter(task => 
  task.action === 'github' || 
  task.type === 'bug' || 
  (task.priority === 'high' && task.type !== 'feedback')
);

return githubTasks.map(task => ({
  task: task,
  chatId: $input.first().json.chatId
}));

